int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    unordered_map<string, long long> ratings;
    for (int i = 0; i < n; i++) {
        string name;
        long long r;
        cin >> name >> r;
        ratings[name] = r;
    }
    vector<pair<string, string>> edges(m);
    for (auto& e : edges) cin >> e.first >> e.second;
    int q;
    cin >> q;
    vector<pair<string, int>> queries(q);
    for (auto& qu : queries) cin >> qu.first >> qu.second;
    auto res = topSimilar(ratings, edges, queries);
    for (auto& r : res) {
        if (r.empty()) {
            cout << "NONE\n";
            continue;
        }
        for (size_t i = 0; i < r.size(); i++) cout << r[i] << (i + 1 < r.size() ? " " : "\n");
    }
    return 0;
}

