import java.util.*;
import java.io.*;

public class Main {
    static List<List<String>> topSimilar(Map<String, Long> ratings, List<String[]> edges, List<Object[]> queries) {
        // Write your solution here
        // Each query is {String name, Integer k}. Return up to k names per query (best first).
        List<List<String>> res = new ArrayList<>();
        for (int i = 0; i < queries.size(); i++) res.add(new ArrayList<>());
        return res;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken()), m = Integer.parseInt(st.nextToken());
        Map<String, Long> ratings = new HashMap<>();
        for (int i = 0; i < n; i++) {
            String name = st.nextToken();
            ratings.put(name, Long.parseLong(st.nextToken()));
        }
        List<String[]> edges = new ArrayList<>();
        for (int i = 0; i < m; i++) edges.add(new String[]{st.nextToken(), st.nextToken()});
        int q = Integer.parseInt(st.nextToken());
        List<Object[]> queries = new ArrayList<>();
        for (int i = 0; i < q; i++) {
            String name = st.nextToken();
            queries.add(new Object[]{name, Integer.parseInt(st.nextToken())});
        }
        StringBuilder sb = new StringBuilder();
        for (List<String> r : topSimilar(ratings, edges, queries)) {
            sb.append(r.isEmpty() ? "NONE" : String.join(" ", r)).append("\n");
        }
        System.out.print(sb);
    }
}
